/**
 * Phase 4 curated disease expansion — official EPPO/FAO/USDA-aligned entities.
 * Scientific names and EPPO codes from public EPPO Global Database / FAO IPPM.
 * No invented chemical doses.
 */
import type { DiseaseEntity, LangMap } from "./crops";

const L = (uz: string, ru: string, kk: string, ky: string, en: string): LangMap => ({
  uz,
  ru,
  kk,
  ky,
  en,
});

type Seed = {
  id: string;
  scientificName: string;
  eppoCode?: string;
  pathogenType: DiseaseEntity["pathogenType"];
  en: string;
  uz: string;
  ru: string;
  crops: string[];
  severity: DiseaseEntity["severity"];
  earlyEn: string;
  lateEn: string;
  condEn: string;
  prevEn: string;
  org: "EPPO" | "FAO" | "USDA";
  url: string;
  confusedWith?: string[];
};

function expand(s: Seed): DiseaseEntity {
  return {
    id: s.id,
    scientificName: s.scientificName,
    eppoCode: s.eppoCode,
    pathogenType: s.pathogenType,
    names: L(s.uz, s.ru, s.ru, s.ru, s.en),
    cropIds: s.crops,
    severity: s.severity,
    earlySymptoms: L(s.earlyEn, s.earlyEn, s.earlyEn, s.earlyEn, s.earlyEn),
    lateSymptoms: L(s.lateEn, s.lateEn, s.lateEn, s.lateEn, s.lateEn),
    conditions: L(s.condEn, s.condEn, s.condEn, s.condEn, s.condEn),
    prevention: L(s.prevEn, s.prevEn, s.prevEn, s.prevEn, s.prevEn),
    confusedWith: s.confusedWith,
    sourceUrl: s.url,
    organization: s.org,
  };
}

